-- GENERATED by gen_mxh3_vault.py -- models are generated, never hand-edited.
--   SAT_CLAIM_PAYMENT_TRANCHE
--   anchor      : HUB_CLAIM
--   grain       : Multi-Active SCD2 (data_7.js sats[].hist)
--   child key   : Tranche Number
--   feeders     : 1 -- one per (view, DECLARED ANCHOR EXPRESSION)
--   payload     : 3 attribute(s), NULL-PADDED TO THE SATELLITE
--
--   The child key is the MODEL'S declared key, read from data_7.js
--   sats[].childkey keyed by sats[].code. target.key_name is the HUB key
--   name and is null on all 1,888 satellite rows, so it is never read here.
--
--   The hashdiff is GUARDED against an all-null input: without the guard
--   every all-null row hashes to ONE value and the population collapses.

with feeders as (select * from (
    select
        md5(upper(HUB_CLAIM_BK__K0)) as HUB_CLAIM_HK,
        coalesce(nullif(trim(INVOICE_NUMBER),''),'') as TRANCHE_NUMBER,
        PURPOSE as PAYMENT_TYPE,
        PAYMENT_AMOUNT as GROSS_AMOUNT,
        PAYMENT_STATUS as STATUS,
        'MAXI_HLTH_CLM_VW_DATA_CLAIM_DETAIL_CLAIM_PAYMENT_PAYMENT_CYCLE_PAYMENT_CYCLE_DETAILS_PIVOT_VW' as RECORD_SOURCE,
        current_timestamp() as LOAD_DATETIME
    from {{ ref('stage_clm_cd_clm_payment_pcy_pcd_pv') }}
    where HUB_CLAIM_K0__EMIT
)), hashed as (select *,
        case when PAYMENT_TYPE is not null or GROSS_AMOUNT is not null or STATUS is not null
             then md5(upper(coalesce(PAYMENT_TYPE::varchar,'') || '||' || coalesce(GROSS_AMOUNT::varchar,'') || '||' || coalesce(STATUS::varchar,'')))
        end as SAT_CLAIM_PAYMENT_TRANCHE_HASHDIFF
    from feeders)

select * from hashed
where HUB_CLAIM_HK is not null
  and SAT_CLAIM_PAYMENT_TRANCHE_HASHDIFF is not null
  and TRANCHE_NUMBER is not null
